package com.agacostays.payroll.mapper; import com.agacostays.payroll.entity.StaffBankAccount; import com.agacostays.payroll.dto.response.StaffBankAccountResponse; import org.springframework.stereotype.Component; @Component public class StaffBankAccountMapper{public StaffBankAccountResponse toResponse(StaffBankAccount x){String n=x.getAccountNumber();String m=n==null?"":(n.length()<=4?"****":"****"+n.substring(n.length()-4));return new StaffBankAccountResponse(x.getBankAccountId(),x.getStaffId(),x.getAccountHolderName(),x.getBankName(),m,x.getIfscCode(),x.getBranchName(),x.getAccountType(),x.getStatus().name(),x.getUpdatedAt());}}